theorem chunk_size_le_price {X : Type*} [MetricSpace X] {s t : X}
    {cLo cHi total price : ℝ} {mL : ℕ} (C : ChunkSystemB X s t cLo cHi total price mL)
    (hp : 0 ≤ price) (ω : C.Ω) (i : Fin C.m) : C.size ω i ≤ price

theorem chunk_two_point_total_le_dist {X : Type*} [MetricSpace X] {s t : X}
    {cLo cHi total price : ℝ} {mL : ℕ} (C : ChunkSystemB X s t cLo cHi total price mL)
    (hst : s ≠ t) (htwo : ∀ x : X, x = s ∨ x = t) : total ≤ dist s t

theorem BookProof.RitzMinMax.exists_le_finrank_eq {S : Submodule ℂ F} [FiniteDimensional ℂ S] {n : ℕ}
    (hn : n ≤ Module.finrank ℂ S) :
    ∃ S₀ : Submodule ℂ F, S₀ ≤ S ∧ Module.finrank ℂ S₀ = n

theorem ShiShallow.isLocal_conj {n : ℕ} {T G : Finset (Fin n)} {A V : Op n}
    (hA : IsLocal T A) (hV : IsLocal G V) :
    IsLocal (G ∪ T) (V.conjTranspose * A * V)

theorem BookProof.ChapterSirkTrotterKato.hasDerivAt_stoneU_const_sub_incr (S : UnboundedSelfAdjoint H) {y : ℝ → H} {y' : H}
    {t u : ℝ} (hy : HasDerivAt y y' u) :
    HasDerivAt (fun r : ℝ => S.stoneU (t - r) (y r - y u)) (S.stoneU (t - u) y') u

theorem ShiShallow.sum_norm_sq_apply1 {n : ℕ} {U : Matrix Bool Bool ℂ}
    (hU : U.conjTranspose * U = 1) (i : Fin n) (ψ : QState n) :
    ∑ x : Bits n, ‖apply1 U i ψ x‖ ^ 2 = ∑ x : Bits n, ‖ψ x‖ ^ 2

theorem ShiShallow.conj_eq_of_disjoint {n : ℕ} {G T : Finset (Fin n)} {A V : Op n}
    (hA : IsLocal T A) (hV : IsLocal G V) (hd : Disjoint G T)
    (hVu : V.conjTranspose * V = 1) : V.conjTranspose * A * V = A

theorem BookProof.ChapterSirkRitzSpectrum.ritzSet_finiteModeRestrict_eq (A : F →L[ℂ] F) (b : HilbertBasis ℕ ℂ F) :
    ritzSet (finiteModeRestrict A b) (finiteModeDomain b) =
      {t : ℝ | ∃ u : F, u ∈ finiteModeDomain b ∧ ‖u‖ = 1 ∧ t = (inner ℂ u (A u) : ℂ).re}

theorem BookProof.ChapterContinuityUnitaryInfinite.bornRecover_union (v : LinfZ) (t : ℝ) (psi : L2Z) {B C : Finset ℤ}
    (h : Disjoint B C) :
    bornRecover v t psi (B ∪ C) = bornRecover v t psi B + bornRecover v t psi C

